private void triggerEvaluationIfSecond(Zone zone, long newCaseId, LocalDateTime now) {
    List<Zone> all = jdbc.sql("SELECT id, code, name, adjacent_codes FROM archive_zone").query(zoneMapper).list();
    Map<String, List<String>> adjacency = ...;
    // BFS cluster
    Set<String> cluster = new LinkedHashSet<>();
    Deque<String> queue = new ArrayDeque<>();
    queue.add(zone.code());
    while (!queue.isEmpty()) {
        String code = queue.poll();
        if (cluster.add(code)) queue.addAll(adjacency.getOrDefault(code, List.of()));
    }
    List<String> sorted = cluster.stream().sorted().toList();
    String placeholders = String.join(", ", Collections.nCopies(sorted.size(), "?"));
    LocalDateTime since = now.minusDays(ADJACENT_WINDOW_DAYS);
    StatementSpec spec = jdbc.sql("SELECT COUNT(*) FROM pest_case c JOIN archive_zone z ON c.zone_id = z.id WHERE z.code IN (" + placeholders + ") AND c.reported_at >= ? AND c.id <> ?");
    for (String code : sorted) spec = spec.param(code);
    spec = spec.param(since).param(newCaseId);
    long prior = spec.query(Long.class).single();
    if (prior == 1) {
        jdbc.sql("INSERT INTO preventive_evaluation (zone_codes, trigger_case_id, reason, created_at) VALUES (?, ?, ?, ?)")
            .params(String.join(",", sorted), newCaseId, "相邻库区 90 日内连续第 2 次虫情，触发整体预防性消杀评估", now).update();
    }
}
