@Test
void concurrentSameKeySameParamsReturnFirstResult() throws Exception {
    int threads = 8;
    ExecutorService pool = Executors.newFixedThreadPool(threads);
    CountDownLatch ready = new CountDownLatch(threads);
    CountDownLatch start = new CountDownLatch(1);
    Map<String, Object> body = Map.of("requestId", "rpt-conc", "reporter", "张三", "description", "发现虫迹");
    List<Future<MvcResult>> futures = new ArrayList<>();
    for (int i = 0; i < threads; i++) {
        futures.add(pool.submit(() -> {
            ready.countDown();
            start.await();
            return mockMvc.perform(post("/api/zones/A/pest-reports")
                    .contentType(MediaType.APPLICATION_JSON)
                    .content(objectMapper.writeValueAsString(body)))
                .andReturn();
        }));
    }
    ready.await(10, TimeUnit.SECONDS);
    start.countDown();
    Set<Long> caseIds = new HashSet<>();
    for (Future<MvcResult> f : futures) {
        MvcResult r = f.get(30, TimeUnit.SECONDS);
        assertEquals(200, r.getResponse().getStatus());
        caseIds.add(objectMapper.readTree(r.getResponse().getContentAsString()).get("caseId").asLong());
    }
    pool.shutdown();
    assertEquals(1, caseIds.size());
    Long count = jdbc.queryForObject("SELECT COUNT(*) FROM pest_case", Long.class);
    assertEquals(1, count);
}
